import importlib.util
import torch
spec = importlib.util.spec_from_file_location('recorded_fused', 'framework/verl/utils/experimental/torch_functional.py')
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)
mod._FLASH_ATTN_CROSS_ENTROPY_AVAILABLE = False
ids = torch.tensor([[0, 1, 2, 3, 4, 5, 6, 7]])
rolled = ids.roll(-1, -1)
hidden = torch.eye(8).unsqueeze(0)
weights = torch.eye(8) * 4
print('Full input IDs:', ids.tolist())
print('Globally shifted targets:', rolled.tolist())
for rank in range(2):
    h = hidden[:, rank * 4:(rank + 1) * 4].clone().requires_grad_()
    w = weights.clone().requires_grad_()
    wrong_lp, entropy = mod.FusedLinearForPPO()(h, w, rolled)
    correct_targets = rolled[:, rank * 4:(rank + 1) * 4]
    correct_lp = (h @ w.T).log_softmax(-1).gather(-1, correct_targets.unsqueeze(-1)).squeeze(-1)
    used_targets = rolled[:, :4]
    bad_grad, = torch.autograd.grad(wrong_lp.sum(), h, retain_graph=True)
    good_grad, = torch.autograd.grad(correct_lp.sum(), h)
    print(f'SP rank {rank}: hidden_shape={list(h.shape)}, passed_target_shape={list(rolled.shape)}')
    print('  Fused kernel actually consumes:', used_targets.tolist(), '; expected:', correct_targets.tolist())
    print('  Output shape:', list(wrong_lp.shape), '; finite:', bool(torch.isfinite(wrong_lp).all()))
    print('  Max log-prob error:', (wrong_lp - correct_lp).abs().max().item())
    print('  Max hidden-gradient error:', (bad_grad - good_grad).abs().max().item())
